document.addEventListener("DOMContentLoaded", function () {
    // Initialize tooltips
    [].slice.call(document.querySelectorAll("[data-bss-tooltip]")).map(function (t) {
        return new bootstrap.Tooltip(t);
    });

    const mainNav = document.getElementById("mainNav");
    const navCollapse = document.getElementById("navbarResponsive");

    function closeMobileMenu() {
        if (navCollapse && navCollapse.classList.contains("show") && typeof bootstrap !== "undefined") {
            const bsCollapse = bootstrap.Collapse.getInstance(navCollapse) || new bootstrap.Collapse(navCollapse, { toggle: false });
            bsCollapse.hide();
        }
    }

    function scrollToTop(e) {
        const isHome = window.location.pathname === "/" || window.location.pathname === "/index.html";
        if (isHome) {
            if (e) e.preventDefault();
            try {
                window.scrollTo({ top: 0, left: 0, behavior: "smooth" });
            } catch (_) {}
            try {
                document.documentElement.scrollTo({ top: 0, left: 0, behavior: "smooth" });
            } catch (_) {}
            try {
                document.body.scrollTo({ top: 0, left: 0, behavior: "smooth" });
            } catch (_) {}

            if (window.location.hash) {
                history.pushState(null, "", window.location.pathname);
            }
            closeMobileMenu();
        }
    }

    // Global click delegation for navbar brand and nav links
    document.addEventListener("click", function (e) {
        const brand = e.target.closest("#mainNav .navbar-brand");
        if (brand) {
            const isHome = window.location.pathname === "/" || window.location.pathname === "/index.html";
            if (isHome) {
                scrollToTop(e);
            }
            return;
        }

        const navLink = e.target.closest("#mainNav .nav-link");
        if (navLink) {
            const href = navLink.getAttribute("href");
            const isHome = window.location.pathname === "/" || window.location.pathname === "/index.html";

            if (href === "/" || href === "/#" || href === "#" || href === "#page-top") {
                if (isHome) {
                    scrollToTop(e);
                    return;
                }
            } else if (href && href.startsWith("#") && href.length > 1) {
                e.preventDefault();
                closeMobileMenu();
                try {
                    const target = document.querySelector(href);
                    if (target) {
                        const offset = mainNav ? mainNav.offsetHeight : 70;
                        const targetPos = target.offsetTop - offset;
                        try {
                            window.scrollTo({ top: targetPos, left: 0, behavior: "smooth" });
                        } catch (_) {}
                        try {
                            document.documentElement.scrollTo({ top: targetPos, left: 0, behavior: "smooth" });
                        } catch (_) {}
                        try {
                            document.body.scrollTo({ top: targetPos, left: 0, behavior: "smooth" });
                        } catch (_) {}
                        history.pushState(null, "", href);
                    }
                } catch (_) {}
                return;
            }
            closeMobileMenu();
        }
    });

    // Handle initial hash on page load
    if (window.location.hash) {
        if (window.location.hash === "#" || window.location.hash === "#page-top") {
            setTimeout(function () {
                scrollToTop();
                history.replaceState(null, "", window.location.pathname);
            }, 0);
        } else if (window.location.hash.length > 1) {
            setTimeout(function () {
                try {
                    const target = document.querySelector(window.location.hash);
                    if (target) {
                        const offset = mainNav ? mainNav.offsetHeight : 70;
                        const targetPos = target.offsetTop - offset;
                        try {
                            window.scrollTo({ top: targetPos, left: 0, behavior: "smooth" });
                        } catch (_) {}
                        try {
                            document.documentElement.scrollTo({ top: targetPos, left: 0, behavior: "smooth" });
                        } catch (_) {}
                        try {
                            document.body.scrollTo({ top: targetPos, left: 0, behavior: "smooth" });
                        } catch (_) {}
                    }
                } catch (_) {}
            }, 50);
        }
    }
});